// One ProcureGuard event in, one formatted message out.
// Decides which team must act, builds the email text, and flags whether a person is needed.
const e = $input.first().json.body ?? $input.first().json;
const p = e.payload || {};
const rs = v => (v === null || v === undefined || v === '') ? '-' : 'Rs ' + Number(v).toLocaleString('en-IN');
const FORM = 'http://localhost:5678/form/bank-change-callback';
let team = 'log_only', subject = e.event, text = '';

switch (e.event) {
  case 'APPROVAL_REQUIRED':
    team = 'finance_controller';
    subject = `Approval needed: ${p.invoice_id} for ${rs(p.amount_inr)}`;
    text = `ProcureGuard has parked a payment for your approval.\n\nInvoice: ${p.invoice_id}\nAmount: ${rs(p.amount_inr)}\nWhy: ${p.reason}\nAgent's note: ${p.agent_note || '-'}\n\nOpen the Approvals tab in ProcureGuard to approve or reject. The MCP server re-checks every control before money moves.`;
    break;
  case 'VENDOR_RISK_ALERT':
    team = p.bank_change_in_cooling_period ? 'vendor_master' : 'finance_controller';
    subject = `Vendor risk ${p.risk_band}: ${p.vendor_name} (${p.vendor_id})`;
    text = `Risk score ${p.risk_score}/100 (${p.risk_band}).\nTriggered factors: ${(p.triggered || []).join(', ') || 'none'}.\n`;
    if (p.bank_change_in_cooling_period) {
      text += `\nBank details changed inside the cooling period, so all payments to this vendor are FROZEN.\n` +
              `Call the authorised contact on the phone number ON FILE in the contract (never a number from the change request),\n` +
              `then record the result here: ${FORM}`;
    }
    break;
  case 'INJECTION_DETECTED':
    team = 'internal_audit';
    subject = `Prompt-injection attempt in ${p.source} of ${p.invoice_id}`;
    text = `Supplier text tried to instruct the AI agents.\nRed flags: ${(p.red_flags || []).join(', ')}.\nThe agents ignored it and the invoice was not paid. Please review the supplier.`;
    break;
  case 'SERVER_CONTROL_REJECTION':
    team = 'internal_audit';
    subject = `Payment refused by server controls: ${p.invoice_id}`;
    text = `The MCP server refused a payment that had passed the client gate.\nReasons:\n- ${(p.reasons || []).join('\n- ')}`;
    break;
  case 'GATE_BLOCKED':
    team = 'internal_audit';
    subject = `Policy gate blocked ${p.tool}`;
    text = `Blocked call: ${p.tool} ${JSON.stringify(p.arguments)}\nReason: ${p.reason}`;
    break;
  case 'INVOICE_ON_HOLD':
    team = 'ap_team';
    subject = `${p.invoice_id} put on hold`;
    text = `Reason: ${p.reason}`;
    break;
  case 'PAYMENT_RELEASED':
    team = 'treasury_log';
    subject = `Paid ${p.invoice_id}: ${rs(p.amount_inr)} (${p.reference})`;
    text = `New bank balance: ${rs(p.new_bank_balance_inr)}`;
    break;
  case 'APPROVAL_DECISION':
    team = 'treasury_log';
    subject = `${p.approver} ${p.decision} ${p.invoice_id} (${rs(p.amount_inr)})`;
    break;
  default:
    subject = `Event ${e.event}`;
    text = JSON.stringify(p);
}

const TO = {
  finance_controller: 'finance.controller@procureguard.example',
  vendor_master: 'vendor.master@procureguard.example, finance.controller@procureguard.example',
  internal_audit: 'internal.audit@procureguard.example, finance.controller@procureguard.example',
};
return [{ json: {
  event_id: e.event_id, event: e.event, severity: e.severity, agent: e.agent, about: e.key || '',
  team, needs_person: Boolean(TO[team]), to: TO[team] || '',
  subject: `[ProcureGuard ${String(e.severity).toUpperCase()}] ${subject}`,
  text: text + `\n\nBusiness date ${e.business_date} | event ${e.event_id} | raised by ${e.agent}`,
  payload: JSON.stringify(p), occurred_at: e.occurred_at,
} }];
